-- query 9
-- @result_contains=east
-- @result_contains=west
SELECT key_projection_001_with_stable_identity
FROM mv_wide ORDER BY key_projection_001_with_stable_identity;

-- query 10
-- Encoded D exceeds 64 KiB. The public rejection includes document kind/name,
-- measured bytes and the supported limit; CREATE must leave no visible table.
-- @expect_error=exceeding limit 65536
CREATE MATERIALIZED VIEW oversized_mv
DISTRIBUTED BY HASH(k) BUCKETS 1 REFRESH DEFERRED MANUAL
PROPERTIES ('storage_engine' = 'iceberg')
AS SELECT k, CONCAT(k, '') AS wide_value FROM fact;

-- query 11
-- @result_contains=OVERSIZED_MV_NOT_VISIBLE
shell: set -eu
response_file="$(mktemp "${TMPDIR:-/tmp}/novarocks-oversized-XXXXXX.json")"
trap 'rm -f "$response_file"' EXIT
status="$(curl --silent --show-error --output "$response_file" --write-out '%{http_code}' '${iceberg_rest_uri}/v1/namespaces/ns_${uuid0}/tables/oversized_mv')"
test "$status" = 404
printf '%s\n' OVERSIZED_MV_NOT_VISIBLE

-- query 12
-- @cleanup=true
-- @skip_result_check=true
SET CATALOG mvside_${uuid0};
USE ns_${uuid0};
DROP MATERIALIZED VIEW IF EXISTS mv_wide;
DROP TABLE mvside_${uuid0}.ns_${uuid0}.fact FORCE;
DROP DATABASE mvside_${uuid0}.ns_${uuid0};
DROP CATALOG mvside_${uuid0};
